/**
 * Updates project metadata.
 *
 * Owner D. Visibility is part of this payload, which is why the permission
 * resource carries the *incoming* visibility: raising a project to `public`
 * must be judged against what it is becoming, not what it was.
 *
 * Must call (do not reimplement): updateProjectSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { updateProjectSchema, type UpdateProjectInput } from "@/schemas/project";
import { updateProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";

const run = withAction<typeof updateProjectSchema, Project>(
  updateProjectSchema,
  async (raw, actor) => {
    const input = raw as UpdateProjectInput;

    const allowed = can(actor, "project:update", {
      kind: "project",
      orgId: input.orgId,
      projectId: input.projectId,
      visibility: input.visibility ?? "org",
      leadId: input.leadId ?? actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:update");
    }

    const project = await updateProject(actor, input);
    revalidateTagged([projectTag(project.id)], CACHE_PROFILES.minutes);
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function updateProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";
import type { PermissionResource } from "@/types/permission";
import type { Project } from "@/types/project";
import type { WebhookId } from "@/types/common";

/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

export function orgResource(orgId: OrgId): PermissionResource {
  return { kind: "organization", orgId };
}

export function billingResource(orgId: OrgId): PermissionResource {
  return { kind: "billing", orgId };
}

export function activityResource(orgId: OrgId): PermissionResource {
  return { kind: "activity", orgId };
}

export function notificationResource(
  orgId: OrgId,
  recipientId: UserId,
): PermissionResource {
  return { kind: "notification", orgId, recipientId };
}

export function webhookResource(
  orgId: OrgId,
  webhookId: WebhookId | null,
): PermissionResource {
  return { kind: "webhook", orgId, webhookId };
}

export function memberResource(member: Member): PermissionResource {
  return {
    kind: "member",
    orgId: member.orgId,
    memberId: member.id,
    targetUserId: member.userId,
    targetRole: member.role,
  };
}

export function projectResource(project: Project): PermissionResource {
  return {
    kind: "project",
    orgId: project.orgId,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  };
}

export function issueResource(issue: Issue): PermissionResource {
  return {
    kind: "issue",
    orgId: issue.orgId,
    projectId: issue.projectId,
    issueId: issue.id,
    authorId: issue.authorId,
    assigneeId: issue.assigneeId,
  };
}

export function commentResource(comment: Comment): PermissionResource {
  return {
    kind: "comment",
    orgId: comment.orgId,
    commentId: comment.id,
    authorId: comment.authorId,
  };
}

/** The three fields the bus stamps on every payload. */
export function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {
  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };
}

/** Same envelope, taken from an `Actor` rather than assembled by hand. */
export function actorEnvelope(actor: Actor): EventEnvelope {
  return envelope(actor.orgId, actor.userId);
}

/** Names the fields an update actually changed, for `issue.updated`. */
export function changedFields<T extends object>(
  before: T,
  after: T,
): readonly string[] {
  return Object.keys(after).filter(
    (key) =>
      JSON.stringify(before[key as keyof T]) !==
      JSON.stringify(after[key as keyof T]),
  );
}

"use client";

/**
 * Editor for name, description, visibility, status, lead and colour.
 *
 * Owner D. Private to the project settings route. `updateProjectSchema` makes
 * every field optional, so the form sends the whole set and lets the service
 * diff them — which is also what produces `changedFields` on the event.
 */

import { useActionState } from "react";
import { fieldErrorsFromZod } from "@/lib/errors";
import { updateProjectSchema } from "@/schemas/project";
import type { ActionResult } from "@/types/api";
import type { OrgId, UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";
import type { Project } from "@/types/project";

export type ProjectSettingsFormProps = {
  orgId: OrgId;
  project: Project;
  members: readonly MemberWithUser[];
  onSubmit: (input: unknown) => Promise<ActionResult<Project>>;
};

type SettingsState = ActionResult<Project> | null;

export function ProjectSettingsForm(props: ProjectSettingsFormProps) {
  const { orgId, project, members, onSubmit } = props;

  const [state, submit, pending] = useActionState<SettingsState, FormData>(
    async (_previous, formData) => {
      const leadId = String(formData.get("leadId") ?? "");
      const description = String(formData.get("description") ?? "").trim();

      const parsed = updateProjectSchema.safeParse({
        orgId,
        projectId: project.id,
        name: String(formData.get("name") ?? ""),
        description: description.length === 0 ? null : description,
        visibility: String(formData.get("visibility") ?? project.visibility),
        status: String(formData.get("status") ?? project.status),
        color: String(formData.get("color") ?? project.color),
        leadId: leadId.length === 0 ? null : (leadId as UserId),
      });

      if (!parsed.success) {
        return {
          ok: false,
          error: {
            code: "validation_failed",
            message: "Check the fields below.",
            fieldErrors: fieldErrorsFromZod(parsed.error),
          },
        };
      }

      return onSubmit(parsed.data);
    },
    null,
  );

  const fieldErrors = state?.ok === false ? (state.error.fieldErrors ?? {}) : {};

  return (
    <form action={submit} className="space-y-5">
      {state?.ok === true ? (
        <p className="rounded bg-emerald-50 px-3 py-2 text-sm text-emerald-700">
          Project updated.
        </p>
      ) : null}

      <div className="space-y-1">
        <label htmlFor="name" className="text-sm font-medium">
          Name
        </label>
        <input
          id="name"
          name="name"
          defaultValue={project.name}
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
        />
        {fieldErrors.name !== undefined ? (
          <p className="text-xs text-rose-600">{fieldErrors.name[0]}</p>
        ) : null}
      </div>

      <div className="space-y-1">
        <label htmlFor="description" className="text-sm font-medium">
          Description
        </label>
        <textarea
          id="description"
          name="description"
          rows={4}
          defaultValue={project.description ?? ""}
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
        />
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <div className="space-y-1">
          <label htmlFor="visibility" className="text-sm font-medium">
            Visibility
          </label>
          <select
            id="visibility"
            name="visibility"
            defaultValue={project.visibility}
            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
          >
            <option value="private">Private — people on the project</option>
            <option value="org">Organization — everybody here</option>
            <option value="public">Public — anybody with the link</option>
          </select>
        </div>

        <div className="space-y-1">
          <label htmlFor="status" className="text-sm font-medium">
            Status
          </label>
          <select
            id="status"
            name="status"
            defaultValue={project.status}
            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
          >
            <option value="active">Active</option>
            <option value="paused">Paused</option>
            <option value="completed">Completed</option>
          </select>
        </div>
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <div className="space-y-1">
          <label htmlFor="leadId" className="text-sm font-medium">
            Lead
          </label>
          <select
            id="leadId"
            name="leadId"
            defaultValue={project.leadId ?? ""}
            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
          >
            <option value="">No lead</option>
            {members.map((member) => (
              <option key={member.id} value={member.userId}>
                {member.user.name}
              </option>
            ))}
          </select>
        </div>

        <div className="space-y-1">
          <label htmlFor="color" className="text-sm font-medium">
            Colour
          </label>
          <input
            id="color"
            name="color"
            type="color"
            defaultValue={project.color}
            className="h-9 w-16 rounded border border-slate-300"
          />
        </div>
      </div>

      <button
        type="submit"
        disabled={pending}
        className="rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-60"
      >
        {pending ? "Saving…" : "Save project"}
      </button>
    </form>
  );
}
